window.__KB__ = JSON.parse('[{"id": "非谓语动词", "category": "语法·句法", "name": "非谓语动词", "level": "进阶", "strength": "rule", "summary": "动词不作谓语时的形式（to do / doing / done），在句中作主语、宾语、定语、状语等。", "rule": "非谓语动词包括不定式(to do)、动名词/现在分词(doing)、过去分词(done)；它们不能单独作谓语，可在句中充当主语、宾语、表语、定语、状语或补语。逻辑主语决定形式：主动/进行用 doing，被动/完成用 done，将来/目的用 to do。", "examples": [{"sentence": "Seeing is believing.", "source": "英语谚语", "answer": "动名词 seeing 作主语，believing 作表语"}, {"sentence": "The woman talking to the teacher is my mother.", "source": "教材例句", "answer": "现在分词 talking 作后置定语，表主动进行"}, {"sentence": "The problem discussed at the meeting was very important.", "source": "高考真题改编", "answer": "过去分词 discussed 作后置定语，表被动完成"}, {"sentence": "I have something to do.", "source": "教材例句", "answer": "不定式 to do 作后置定语，表将来"}], "commonErrors": [{"wrong": "He came to the party wear a costume.", "right": "He came to the party wearing a costume.", "why": "wear 应为 wearing，作伴随状语用现在分词"}, {"wrong": "The boy stand there is my brother.", "right": "The boy standing there is my brother.", "why": "stand 应为 standing，作后置定语用现在分词"}], "confusionPoints": [{"point": "不定式 vs 现在分词作状语", "detail": "不定式作状语多表目的或结果；现在分词作状语多表伴随、原因、时间。例：He ran to catch the bus（目的）vs He ran, laughing all the way（伴随）"}, {"point": "现在分词 vs 过去分词作定语", "detail": "现在分词表主动/进行；过去分词表被动/完成。例：the girl singing（主动）vs the song sung（被动）"}], "tags": ["语法", "非谓语"], "related": ["定语从句", "状语从句", "强调句"]}, {"id": "定语从句", "category": "语法·句法", "name": "定语从句", "level": "基础", "strength": "rule", "summary": "用关系词引导从句修饰名词或代词（先行词），关系词在从句中充当成份。", "rule": "定语从句由关系代词(who/whom/which/that/whose/as)或关系副词(when/where/why)引导，修饰前面的先行词；关系词在从句中必须充当主语、宾语、定语或状语。作主语时关系词不可省略；作宾语时（非介词后）可省略。", "examples": [{"sentence": "The man who came here yesterday is my teacher.", "source": "教材例句", "answer": "who 指人，作主语"}, {"sentence": "This is the book which I bought yesterday.", "source": "教材例句", "answer": "which 指物，作宾语，可省略"}, {"sentence": "The girl whose hair is red is from America.", "source": "高考真题改编", "answer": "whose 作定语，可指人也可指物"}, {"sentence": "He lives in the house where he was born.", "source": "高考真题改编", "answer": "where 作地点状语，相当于 in which"}], "commonErrors": [{"wrong": "This is the city where I visited last year.", "right": "This is the city which/that I visited last year.", "why": "visit 是及物动词，从句缺宾语，应用 which/that，不能用 where"}, {"wrong": "The boy whom is talking is my brother.", "right": "The boy who is talking is my brother.", "why": "作主语应用 who，不能用 whom"}], "confusionPoints": [{"point": "只用 that 的情况", "detail": "先行词是不定代词(all, everything 等)、被最高级/序数词/the only 修饰、或既有人又有物时，关系代词只用 that，不用 which。例：This is the best film that I have seen."}, {"point": "whose 的用法", "detail": "whose 既可指人也可指物，在从句中作定语。例：The book whose cover is red is mine.（指物）"}], "tags": ["语法", "从句"], "related": ["名词性从句", "状语从句", "非谓语动词"]}, {"id": "名词性从句", "category": "语法·句法", "name": "名词性从句", "level": "进阶", "strength": "rule", "summary": "在句中起名词作用的从句：主语从句、宾语从句、表语从句、同位语从句。", "rule": "名词性从句由 that、whether/if 或 wh-词(what/who/when/why/how 等)引导，可充当主语、宾语、表语或同位语。that 无意义不充当成分；whether 表是否；wh-词在从句中充当成分。名词性从句一律用陈述语序。", "examples": [{"sentence": "What he said is true.", "source": "教材例句", "answer": "what 引导主语从句，what 作 said 的宾语"}, {"sentence": "I do not know whether he will come.", "source": "教材例句", "answer": "whether 引导宾语从句，表是否"}, {"sentence": "The fact that the earth is round is known to all.", "source": "高考真题改编", "answer": "that 引导同位语从句，解释 fact 的内容"}, {"sentence": "This is because he was ill.", "source": "教材例句", "answer": "because 引导表语从句，表原因"}], "commonErrors": [{"wrong": "That he will come is not sure.", "right": "Whether he will come is not sure.", "why": "主语从句表是否用 whether，不用 that"}, {"wrong": "I do not know what does he want.", "right": "I do not know what he wants.", "why": "名词性从句用陈述语序，不用疑问语序"}], "confusionPoints": [{"point": "that 引导同位语从句 vs 定语从句", "detail": "同位语从句的 that 不充当成分、解释前面名词内容；定语从句的 that 充当成分、修饰先行词。例：the news that he told me（定语，that 作 told 的宾语）vs the news that he won（同位语，that 无成分）"}, {"point": "whether vs if 引导宾语从句", "detail": "whether 可用于介词后及主语/表语/同位语从句；if 一般只用于动词后宾语从句，且不与 or not 紧连。例：It depends on whether he comes."}], "tags": ["语法", "从句"], "related": ["定语从句", "状语从句"]}, {"id": "状语从句", "category": "语法·句法", "name": "状语从句", "level": "基础", "strength": "rule", "summary": "由从属连词引导、在句中作状语，表时间、条件、原因、让步、结果等。", "rule": "状语从句由 when/while/as(时间)、if/unless(条件)、because/since/as(原因)、although/though(让步)、so...that(结果) 等引导。时间/条件状语从句遵循主将从现。", "examples": [{"sentence": "When I arrived, he was reading.", "source": "教材例句", "answer": "when 引导时间状语从句"}, {"sentence": "If it rains, we will stay at home.", "source": "教材例句", "answer": "if 引导条件状语从句，主将从现"}, {"sentence": "Although he was tired, he kept working.", "source": "教材例句", "answer": "although 引导让步状语从句"}, {"sentence": "He spoke so fast that I could not follow him.", "source": "高考真题改编", "answer": "so...that... 引导结果状语从句"}], "commonErrors": [{"wrong": "If it will rain, we will stay.", "right": "If it rains, we will stay.", "why": "条件状语从句用一般现在时表将来，主句用将来时"}, {"wrong": "Though he was tired, but he kept working.", "right": "Though he was tired, he kept working.", "why": "though/although 与 but 不能连用"}], "confusionPoints": [{"point": "when 引导定语从句 vs 状语从句", "detail": "when 引导定语从句时前面有表示时间的先行词；引导状语从句时无先行词。例：I will never forget the day when we met.（定语）vs When I arrived, he was out.（状语）"}, {"point": "if 引导条件状语从句 vs 宾语从句", "detail": "if 引导宾语从句相当于 whether，可用将来时；引导条件状语从句用一般现在时表将来。例：I do not know if he will come.（宾语）vs If he comes, I will tell him.（状语）"}], "tags": ["语法", "从句"], "related": ["定语从句", "名词性从句"]}, {"id": "动词时态", "category": "语法·句法", "name": "动词时态", "level": "基础", "strength": "rule", "summary": "表示动作发生的时间与状态，高考重点在现在完成时、进行时及过去时态的辨析。", "rule": "常见时态：一般现在/过去/将来时表常态或过去/将来动作；现在/过去/将来进行时表某时正在发生；现在/过去完成时强调对现在/过去某时的影响或持续。短暂动词不与 for 时间段连用。", "examples": [{"sentence": "He came here yesterday.", "source": "教材例句", "answer": "一般过去时，表过去发生的动作"}, {"sentence": "She has been teaching for 20 years.", "source": "高考真题改编", "answer": "现在完成进行时，表从过去持续到现在的动作"}, {"sentence": "By next July, I will have graduated.", "source": "教材例句", "answer": "将来完成时，表到将来某时已完成"}, {"sentence": "It was raining when I arrived.", "source": "教材例句", "answer": "过去进行时，表过去某时正在发生"}], "commonErrors": [{"wrong": "I have seen this movie yesterday.", "right": "I saw this movie yesterday.", "why": "yesterday 是明确的过去时间，用一般过去时，不能用现在完成时"}, {"wrong": "He has died for three years.", "right": "He has been dead for three years.", "why": "die 是短暂动词，不能与 for 引导的时间段连用；表持续状态用 be dead，或改为 He died three years ago."}], "confusionPoints": [{"point": "一般过去时 vs 现在完成时", "detail": "一般过去时只表过去动作；现在完成时强调过去动作对现在的影响或持续到现在。例：I lost my key.（只说过去丢了）vs I have lost my key.（强调现在还没找到）"}, {"point": "现在完成时 vs 过去完成时", "detail": "现在完成时以现在为参照；过去完成时以过去某时为参照（过去的过去）。例：When I arrived, the train had already left."}], "tags": ["语法", "时态"], "related": ["被动语态", "主谓一致"]}, {"id": "主谓一致", "category": "语法·句法", "name": "主谓一致", "level": "基础", "strength": "rule", "summary": "谓语动词的数须与主语的人称和数保持一致。", "rule": "谓语与主语一致；主语后接 with/together with/as well as 等短语时仍与主语一致（就远）；either...or.../neither...nor.../not only...but also... 连接并列主语时谓语就近一致；时间/距离/金钱作主语用单数；集合名词强调整体用单数、强调成员用复数。", "examples": [{"sentence": "The teacher, together with his students, is going to the museum.", "source": "高考真题改编", "answer": "主语后有 together with 短语，谓语与主语一致"}, {"sentence": "Either you or I am responsible.", "source": "教材例句", "answer": "either...or... 连接并列主语，谓语就近一致"}, {"sentence": "The police are looking for the thief.", "source": "教材例句", "answer": "police 是集合名词，谓语用复数"}, {"sentence": "Ten years is a long time.", "source": "教材例句", "answer": "时间、距离、金钱作主语，谓语用单数"}], "commonErrors": [{"wrong": "The news are very exciting.", "right": "The news is very exciting.", "why": "news 不可数，谓语用单数"}, {"wrong": "More than one student have failed.", "right": "More than one student has failed.", "why": "more than one + 单数名词作主语，谓语用单数"}], "confusionPoints": [{"point": "就近一致 vs 就远一致", "detail": "either...or..., neither...nor..., not only...but also... 连接并列主语时谓语就近一致；with, together with, as well as 等连接时谓语就远一致（与主语一致）"}, {"point": "集合名词的数", "detail": "people, police, cattle 等集合名词谓语用复数；family, class, team 等强调整体用单数，强调成员用复数"}], "tags": ["语法", "一致"], "related": ["名词", "名词性从句"]}, {"id": "情态动词", "category": "语法·句法", "name": "情态动词", "level": "基础", "strength": "rule", "summary": "表示能力、许可、必要、推测等语气，后接动词原形。", "rule": "情态动词(can/could, may/might, must, should, need, shall/will)后接动词原形；must 表禁止用 must not，表不必用 need not / do not have to；肯定推测用 may/might/must，can 多用于否定/疑问推测。", "examples": [{"sentence": "You must finish your homework first.", "source": "教材例句", "answer": "must 表必须"}, {"sentence": "He can speak three languages.", "source": "教材例句", "answer": "can 表能力"}, {"sentence": "It must have rained last night. The ground is wet.", "source": "高考真题改编", "answer": "must have done 表对过去的肯定推测"}, {"sentence": "You should have come earlier.", "source": "教材例句", "answer": "should have done 表本应做而没做"}], "commonErrors": [{"wrong": "You must not do that. (想表达不必)", "right": "You do not have to do that.", "why": "must not 表禁止；表不必用 do not have to 或 need not"}, {"wrong": "He can be at home now.", "right": "He may/might be at home now.", "why": "can 表推测通常用于否定和疑问句；肯定推测用 may/might"}], "confusionPoints": [{"point": "must 提问的回答", "detail": "Must I...? 肯定回答用 Yes, you must.；否定回答用 No, you need not. / No, you do not have to.（不能用 must not）"}, {"point": "can vs may", "detail": "can 表能力或许可；may 表请求或可能性。例：Can I use your pen?（口语）vs May I use your pen?（正式）"}], "tags": ["语法", "情态"], "related": ["动词时态", "虚拟语气"]}, {"id": "虚拟语气", "category": "语法·句法", "name": "虚拟语气", "level": "进阶", "strength": "rule", "summary": "表示与事实相反或不大可能实现的假设，从句与主句动词形式特殊。", "rule": "与现在/将来事实相反：从句用过去时(be 用 were)，主句 would/could/should do；与过去相反：从句 had done，主句 would have done。wish 后从句用过去时(现在)/had done(过去)/would do(将来)；suggest/demand 等后接 (should) do。", "examples": [{"sentence": "If I were you, I would accept the offer.", "source": "教材例句", "answer": "与现在事实相反，从句过去时(be 用 were)，主句 would do"}, {"sentence": "If I had known earlier, I would have told you.", "source": "高考真题改编", "answer": "与过去事实相反，从句 had done，主句 would have done"}, {"sentence": "I wish I were a bird.", "source": "教材例句", "answer": "wish 后从句用虚拟，与现在相反用过去时"}, {"sentence": "He suggested that we (should) start early.", "source": "教材例句", "answer": "suggest 等词后接 (should) do 虚拟"}], "commonErrors": [{"wrong": "If I was you, I would accept the offer.", "right": "If I were you, I would accept the offer.", "why": "虚拟语气中 be 动词一律用 were"}, {"wrong": "I wish I can fly.", "right": "I wish I could fly.", "why": "wish 后从句用虚拟语气，can 改为 could"}], "confusionPoints": [{"point": "if 真实条件句 vs 虚拟条件句", "detail": "真实条件句：If it rains, we will stay at home.（可能下雨）vs 虚拟条件句：If it rained, we would stay at home.（不可能/与现在相反）"}, {"point": "含蓄虚拟条件句", "detail": "without, but for, otherwise 等可引导含蓄虚拟。例：Without your help, I could not have succeeded.（= If you had not helped me...）"}], "tags": ["语法", "虚拟"], "related": ["动词时态", "情态动词"]}, {"id": "倒装句", "category": "语法·句法", "name": "倒装句", "level": "进阶", "strength": "rule", "summary": "为强调或语法需要，将谓语或部分谓语置于主语之前。", "rule": "否定词(never, seldom, hardly)、only + 状语、not only...but also... 的 not only 分句置于句首需部分倒装(助动词提前)；here/there/now/then + 谓语 + 名词主语 用完全倒装。as 引导让步状语从句需倒装。", "examples": [{"sentence": "Never have I seen such a beautiful place.", "source": "高考真题改编", "answer": "否定词 never 置于句首，句子部分倒装"}, {"sentence": "Only then did I understand the truth.", "source": "教材例句", "answer": "only + 状语置于句首，句子部分倒装"}, {"sentence": "Not only does he sing well, but he also dances well.", "source": "教材例句", "answer": "not only...but also... 连接并列句，not only 分句倒装"}, {"sentence": "Here comes the bus.", "source": "教材例句", "answer": "here 置于句首，主语为名词时完全倒装"}], "commonErrors": [{"wrong": "Never I have seen such a beautiful place.", "right": "Never have I seen such a beautiful place.", "why": "否定词置于句首应部分倒装，助动词提前"}, {"wrong": "Only then I understood the truth.", "right": "Only then did I understand the truth.", "why": "only + 状语置于句首应部分倒装"}], "confusionPoints": [{"point": "完全倒装 vs 部分倒装", "detail": "完全倒装：here/there/now/then + 谓语 + 主语(名词)；部分倒装：否定词/only + 助动词 + 主语 + 谓语动词"}, {"point": "as 引导的让步状语从句倒装", "detail": "as 引导让步状语从句时，名词/形容词/副词/动词提前构成倒装。例：Child as he is, he knows a lot.（名词提前，不加冠词）"}], "tags": ["语法", "倒装"], "related": ["强调句", "写作高级句型"]}, {"id": "强调句", "category": "语法·句法", "name": "强调句", "level": "进阶", "strength": "rule", "summary": "用 It is/was + 被强调部分 + that/who + 其余 结构突出句子某一成分。", "rule": "强调句基本结构为 It is/was + 被强调成分 + that/who + 句子其余部分；被强调部分可是主语、宾语或状语，但不可强调谓语动词；去掉 It is/was...that... 后句子仍完整。指人作主语/宾语时可用 who。", "examples": [{"sentence": "It was Tom that/who broke the window.", "source": "教材例句", "answer": "强调主语 Tom"}, {"sentence": "It was yesterday that I met him.", "source": "教材例句", "answer": "强调时间状语 yesterday"}, {"sentence": "It was not until he came that I left.", "source": "高考真题改编", "answer": "强调 not until 状语，主句需部分倒装"}, {"sentence": "It was in the park that we played.", "source": "教材例句", "answer": "强调地点状语 in the park"}], "commonErrors": [{"wrong": "It was in the park where we played.", "right": "It was in the park that we played.", "why": "强调句用 that/who，不用 where/which"}, {"wrong": "It is him that broke the window.", "right": "It is he that broke the window.", "why": "强调主语时，代词用主格 he"}], "confusionPoints": [{"point": "强调句 vs 定语从句", "detail": "强调句去掉 It is/was...that... 后句子完整；定语从句去掉后不完整。例：It was the park that we visited.（强调，visit 缺宾语由 that 补）vs It was the park where we played.（定语，where 作状语）"}, {"point": "强调句 vs 倒装句", "detail": "强调句结构固定为 It is/was...that...；not only...but also 等引起的倒装无 it is 结构"}], "tags": ["语法", "强调"], "related": ["倒装句", "it的用法"]}, {"id": "被动语态", "category": "语法·句法", "name": "被动语态", "level": "基础", "strength": "rule", "summary": "主语是动作的承受者时，用 be + 过去分词 构成被动语态。", "rule": "被动语态由 be + 过去分词 构成，时态通过 be 体现；及物动词才有被动语态，不及物动词(如 happen, occur, break out, belong to)无被动；短语动词的介词不可省略。", "examples": [{"sentence": "The book was written by Lu Xun.", "source": "教材例句", "answer": "一般过去时的被动语态"}, {"sentence": "The work will be finished tomorrow.", "source": "教材例句", "answer": "一般将来时的被动语态"}, {"sentence": "The room is being cleaned now.", "source": "高考真题改编", "answer": "现在进行时的被动语态"}, {"sentence": "English is spoken all over the world.", "source": "教材例句", "answer": "一般现在时的被动语态"}], "commonErrors": [{"wrong": "The letter has written by him.", "right": "The letter has been written by him.", "why": "现在完成时的被动语态是 have/has been done"}, {"wrong": "The story was happened last year.", "right": "The story happened last year.", "why": "happen 是不及物动词，没有被动语态"}], "confusionPoints": [{"point": "主动语态 vs 被动语态", "detail": "主动强调动作执行者；被动强调承受者。当执行者不重要或不明时，常用被动。例：The window was broken.（不明谁打破）"}, {"point": "不及物动词没有被动语态", "detail": "happen, take place, break out, belong to 等不及物或短语没有被动语态"}], "tags": ["语法", "语态"], "related": ["动词时态", "非谓语动词"]}, {"id": "it的用法", "category": "语法·句法", "name": "it 的用法", "level": "基础", "strength": "rule", "summary": "it 可作形式主语/形式宾语、指代前文事物，或用于强调句。", "rule": "it 可作形式主语/形式宾语、指代上文的单数事物，或作强调句的引导词；形式主/宾语的 it 不可省略。", "examples": [{"sentence": "It is important to study English.", "source": "教材例句", "answer": "it 作形式主语，代替不定式"}, {"sentence": "I find it difficult to learn math.", "source": "教材例句", "answer": "it 作形式宾语，代替不定式"}, {"sentence": "It was he who helped me.", "source": "教材例句", "answer": "it 用于强调句"}, {"sentence": "Who is it? It is me.", "source": "日常对话", "answer": "it 指代不明身份的人"}], "commonErrors": [{"wrong": "I think that is important to study.", "right": "I think it is important to study.", "why": "不定式作主语需用 it 作形式主语"}, {"wrong": "We found that hard to finish.", "right": "We found it hard to finish.", "why": "不定式作宾语补足语需用 it 作形式宾语"}], "confusionPoints": [{"point": "it 形式主语 vs 指示代词", "detail": "形式主语 it 代替后面不定式/从句；指示代词 it 指代前面具体事物。例：It is good to help others.（形式）vs I bought a pen; it is red.（指示）"}, {"point": "it 作形式宾语 vs 真实宾语", "detail": "形式宾语 it 位于动词后，真实宾语(不定式/从句)置后。例：I made it clear that I disagreed."}], "tags": ["语法", "it"], "related": ["强调句", "非谓语动词"], "points": [{"text": "形式主语 / 形式宾语：代替不定式、动名词或从句", "example": "It is important to keep a balanced diet.", "note": "真主语是 to keep a balanced diet，用 it 占位，避免句子头重脚轻。"}, {"text": "指代上文提到的单数事物（也可指婴儿或不确定的人）", "example": "I lost my key yesterday and still can not find it.", "note": "it 回指前一句出现过的 the key 这类单数事物。"}, {"text": "强调句 It is / It was ... that (who) ... 中的引导词", "example": "It was in the library that I first met her.", "note": "去掉 It was ... that 后句子仍完整，说明是强调结构。"}]}, {"id": "独立主格结构", "category": "语法·句法", "name": "独立主格结构", "level": "挑战", "strength": "rule", "summary": "名词/代词 + 非谓语/形容词/副词等构成独立结构，有自己的逻辑主语，作状语。", "rule": "独立主格由 名词/代词 + 现在分词/过去分词/形容词/副词/介词短语 构成，逻辑主语与主句主语不同；常表时间、原因、条件或伴随，与主句用逗号隔开。它不是句子，不可用完整谓语。", "examples": [{"sentence": "Weather permitting, we will go out.", "source": "高考真题改编", "answer": "名词 + 现在分词，表条件"}, {"sentence": "He lay on the grass, his eyes looking at the sky.", "source": "教材例句", "answer": "代词 + 现在分词，表伴随"}, {"sentence": "The meeting over, we went home.", "source": "教材例句", "answer": "名词 + 副词，表时间"}, {"sentence": "All things considered, he is a good student.", "source": "高考真题改编", "answer": "代词 + 过去分词，表原因"}], "commonErrors": [{"wrong": "Weather permits, we will go out.", "right": "Weather permitting, we will go out.", "why": "独立主格用非谓语 permitting，不用谓语 permits"}, {"wrong": "He entered the room, his head was down.", "right": "He entered the room, his head down.", "why": "独立主格不是完整句子，用 名词+形容词/副词 结构，不能用完整谓语"}], "confusionPoints": [{"point": "独立主格 vs 分词作状语", "detail": "独立主格有自己逻辑主语(与主句不同)；分词作状语逻辑主语即主句主语。例：He sitting there,...（独立）vs Sitting there, he...（分词）"}, {"point": "独立主格 vs with 复合结构", "detail": "with + 宾语 + 补语 功能相近，但 with 结构带 with。例：with his head down"}], "tags": ["语法", "独立主格"], "related": ["非谓语动词", "it的用法"]}, {"id": "there be 句型", "category": "语法·句法", "name": "there be 句型", "level": "基础", "strength": "rule", "summary": "表示某处存在某物，be 的数与最靠近的主语一致（就近一致）。", "rule": "there be 表示存在，be 动词遵循就近一致（与紧邻主语一致）；有时态变化(there was/were/will be/has been)；变体 there stand/lie/exist 等用完全倒装；否定加 not，疑问把 be 提前。there be 表存在，不与 have（表所属）混用。", "examples": [{"sentence": "There is a book on the desk.", "source": "教材例句", "answer": "be 与最近主语 a book 单数一致"}, {"sentence": "There are two apples in the bag.", "source": "教材例句", "answer": "be 与复数 two apples 一致"}, {"sentence": "There stands an old tree on the hill.", "source": "高考真题改编", "answer": "there stand 完全倒装变体"}, {"sentence": "There have been great changes.", "source": "教材例句", "answer": "现在完成时 there have been"}], "commonErrors": [{"wrong": "There has a book on the desk.", "right": "There is a book on the desk.", "why": "there be 表存在，不用 have"}, {"wrong": "Have there a library in your school?", "right": "Is there a library in your school?", "why": "there be 疑问句把 be 提前，不用 have"}], "confusionPoints": [{"point": "there be vs have", "detail": "there be 表客观存在；have 表所属。例：There is a book on the desk.（存在）vs I have a book.（拥有）"}, {"point": "就近一致", "detail": "be 与最靠近它的主语一致，不受远处复数影响。例：There is a pen and two books."}], "tags": ["语法", "there be"], "related": ["主谓一致", "倒装句"]}, {"id": "比较结构", "category": "语法·句法", "name": "比较结构", "level": "进阶", "strength": "rule", "summary": "比较级/最高级及 as...as、the more...the more、倍数等比较句型。", "rule": "比较级由 -er/more 构成，最高级由 -est/most 构成并常加 the；as + 原级 + as 表同级比较；比较级 + than；the + 比较级..., the + 比较级... 表越…越…；倍数用 twice/three times 置于 as...as 或比较级前。", "examples": [{"sentence": "He is as tall as his brother.", "source": "教材例句", "answer": "as + 原级 + as 同级比较"}, {"sentence": "The more you read, the more you know.", "source": "教材例句", "answer": "the + 比较级..., the + 比较级... 越…越…"}, {"sentence": "This room is three times as large as that one.", "source": "高考真题改编", "answer": "倍数 + as...as"}, {"sentence": "This is the most interesting book I have read.", "source": "教材例句", "answer": "最高级加 the"}], "commonErrors": [{"wrong": "He is more taller than me.", "right": "He is taller than me.", "why": "单音节形容词比较级加 -er，不用 more"}, {"wrong": "The more better it is.", "right": "The better it is.", "why": "better 本身是比较级，不与 more 连用"}], "confusionPoints": [{"point": "比较级 vs 最高级", "detail": "比较级用于两者；最高级用于三者及以上，常加 the。例：the tallest of the three"}, {"point": "倍数表达位置", "detail": "倍数(twice/three times)置于 as...as 或 比较级 之前。例：twice as large as"}], "tags": ["语法", "比较"], "related": ["形容词", "副词"]}, {"id": "直接引语与间接引语", "category": "语法·句法", "name": "直接引语与间接引语", "level": "进阶", "strength": "rule", "summary": "转述他人话语时，间接引语需调整人称、时态、时间与地点状语。", "rule": "直接引语变间接引语：人称相应变化；主句为过去时则从句时态后移(一般现在→一般过去，现在完成→过去完成)；时间状语 now→then, today→that day；指示代词 this→that；若主句为现在时，从句时态不变（客观真理永不变）。", "examples": [{"sentence": "He said, \'I am tired.\' → He said (that) he was tired.", "source": "教材例句", "answer": "人称与时态后移"}, {"sentence": "She said, \'I will go tomorrow.\' → She said she would go the next day.", "source": "教材例句", "answer": "will→would, tomorrow→the next day"}, {"sentence": "He said, \'This is my book.\' → He said that was his book.", "source": "高考真题改编", "answer": "this→that, my→his"}, {"sentence": "He said the earth moves around the sun.", "source": "教材例句", "answer": "客观真理时态不后移"}], "commonErrors": [{"wrong": "He said that he will come.", "right": "He said that he would come.", "why": "主句为过去时，从句 will 后移为 would"}, {"wrong": "She said she was there now.", "right": "She said she was there then.", "why": "now 应改为 then，地点状语 here 也需相应改为 there"}], "confusionPoints": [{"point": "时态是否后移", "detail": "主句现在时从句不变；主句过去时从句后移（除非客观真理）。例：He said the sun rises in the east."}, {"point": "直接引语标点", "detail": "直接引语用引号与逗号；间接引语用 that 引导（可省），无引号。例：He said, \'...\' vs He said (that)..."}], "tags": ["语法", "引语"], "related": ["动词时态", "名词性从句"]}, {"id": "省略句", "category": "语法·句法", "name": "省略句", "level": "挑战", "strength": "register", "summary": "为避免重复或增强简洁，省略句中可省的成分（主语、谓语、关系词等）。", "rule": "省略常见于：并列句省相同成分；状语从句省略 主语+be（与主句主语一致时）；不定式省略 to 后动词(避免重复)；not/so/neither 引导的省略。不可省到改变句意或破坏结构。", "examples": [{"sentence": "I will go if (it is) necessary.", "source": "教材例句", "answer": "状语从句省略 it is"}, {"sentence": "He is taller than I (am).", "source": "教材例句", "answer": "than 后省略 am"}, {"sentence": "— Can you swim? — No, I can not (swim).", "source": "日常对话", "answer": "不定式/动词省略"}, {"sentence": "When (he was) young, he liked reading.", "source": "教材例句", "answer": "时间状语从句省略 he was"}], "commonErrors": [{"wrong": "I will go there if need.", "right": "I will go there if (it is) necessary.", "why": "状语从句的省略需保留 be 动词或写完整，不能只留 need"}, {"wrong": "He is taller than me. (规范书面语)", "right": "He is taller than I (am).", "why": "规范书面语中 than 后省略 be 动词时主语用主格 I；口语中 than me 也很常见，属语域差异"}], "confusionPoints": [{"point": "状语从句省略条件", "detail": "主语+be 与主句主语一致且 be 为系动词时可省。例：Though (he was) tired, he worked."}, {"point": "than/as 后省略", "detail": "比较结构中 than/as 后常省谓语，保留主语（主格）或宾语。例：He runs faster than I."}], "tags": ["语法", "省略"], "related": ["比较结构", "状语从句"]}, {"id": "祈使句与感叹句", "category": "语法·句法", "name": "祈使句与感叹句", "level": "基础", "strength": "rule", "summary": "祈使句表请求命令（动词原形开头），感叹句表强烈感情（what/how 引导）。", "rule": "祈使句以动词原形开头，否定加 Don\'t/Never；感叹句 What + (a/an) + 形 + 名 + 主谓！/ How + 形/副 + 主谓！what 修饰名词，how 修饰形容词/副词。", "examples": [{"sentence": "Open the window, please.", "source": "教材例句", "answer": "祈使句原形开头"}, {"sentence": "Don\'t be late again.", "source": "教材例句", "answer": "否定祈使句"}, {"sentence": "What a beautiful girl she is!", "source": "教材例句", "answer": "what 修饰名词 girl"}, {"sentence": "How beautiful the girl is!", "source": "教材例句", "answer": "how 修饰形容词 beautiful"}], "commonErrors": [{"wrong": "How a beautiful girl she is!", "right": "What a beautiful girl she is!", "why": "how 不接 a/an + 名词，用 what"}, {"wrong": "Don\'t to be late.", "right": "Don\'t be late.", "why": "祈使句否定用 Don\'t + 动词原形，无 to"}], "confusionPoints": [{"point": "what vs how 引导感叹", "detail": "what 后接名词(可带形容词)；how 后接形容词/副词。例：What fine weather!（weather 不可数无 a）vs How fine the weather is!"}, {"point": "祈使句主语", "detail": "通常省主语 you；加 you 表强调：You be quiet!"}], "tags": ["语法", "句式"], "related": ["形容词", "副词"]}, {"id": "情态动词表推测", "category": "语法·句法", "name": "情态动词表推测", "level": "进阶", "strength": "rule", "summary": "用 may/might/could/must/can\'t 表达推测，可能性等级与语境（肯定/否定/疑问）不同。", "rule": "表推测时可能性由弱到强：might < may < could < must(一定)；must 表肯定推测，can\'t 表否定推测(不可能)；can 表推测一般只用于否定句和疑问句，may well 表完全有可能。对现在/将来的推测用 情态动词+动词原形，对过去的推测用 情态动词+have done。疑问句中表推测多用 can/could。", "examples": [{"sentence": "He might be at home, but I am not sure.", "source": "教材例句", "answer": "might 表可能性较小的推测"}, {"sentence": "She may well be the best player in the team.", "source": "教材例句", "answer": "may well 表完全有可能"}, {"sentence": "It can\'t be true. She is on her way to Beijing.", "source": "高考真题改编", "answer": "can\'t 表否定推测：不可能"}, {"sentence": "The light is on. He must be in the room.", "source": "教材例句", "answer": "must 表有把握的肯定推测"}], "commonErrors": [{"wrong": "He can be at home now.", "right": "He may/might be at home now.", "why": "can 表推测一般只用于否定句和疑问句；肯定句中的推测用 may/might/must"}, {"wrong": "He must not be at home, because the light is off.", "right": "He can\'t be at home, because the light is off.", "why": "must not 表禁止，不表否定推测；否定推测用 can\'t"}], "confusionPoints": [{"point": "might < may < must 的可能性等级", "detail": "must 语气最强（一定/准是），may 次之（可能），might 最弱（也许）。例：He must know the answer.（很有把握）vs He might know it.（不太确定）"}, {"point": "can\'t vs must not", "detail": "can\'t 表推测上的不可能；must not 表禁止。例：It can\'t be him—he is abroad.（不可能是他）vs You must not smoke here.（禁止吸烟）"}], "tags": ["语法", "情态", "推测"], "related": ["情态动词", "情态动词+have done"]}, {"id": "need与dare的用法", "category": "语法·句法", "name": "need 与 dare 的用法", "level": "进阶", "strength": "rule", "summary": "need/dare 兼具实义动词与情态动词两种形态，否定与疑问形式各不相同。", "rule": "need/dare 兼具实义动词与情态动词双重身份：作实义动词时有人称和数的变化，否定/疑问借助 do(does/did)，后接 to do（need to do / dare to do）；作情态动词时无变化，主要用于否定句和疑问句，后接动词原形（need do / dare do）。need doing = need to be done，表被动含义。", "examples": [{"sentence": "You need not worry about it.", "source": "教材例句", "answer": "need 作情态动词，后接动词原形"}, {"sentence": "He needs to finish the work today.", "source": "教材例句", "answer": "need 作实义动词，第三人称单数加 -s，后接 to do"}, {"sentence": "The flowers need watering.", "source": "高考真题改编", "answer": "need doing 表被动，相当于 need to be watered"}, {"sentence": "How dare you say that to me?", "source": "教材例句", "answer": "dare 作情态动词，后接动词原形"}], "commonErrors": [{"wrong": "He need to go now.", "right": "He needs to go now.", "why": "肯定句中 need 一般作实义动词，第三人称单数加 -s 并接 to do；情态动词用法主要用于否定句和疑问句"}, {"wrong": "My hair needs to wash.", "right": "My hair needs washing.", "why": "need 表「需要被…」用 need doing 或 need to be done，hair 与 wash 是被动关系；也可写作 needs to be washed"}], "confusionPoints": [{"point": "need do vs need to do", "detail": "情态动词 need 用于否定/疑问（Need he come?）；实义动词 need 用于各种句式，后接 to do。例：He need not come.（情态）vs He needs to come.（实义）"}, {"point": "need doing vs need to be done", "detail": "两者同义，主语与动词为被动关系；want/require doing 也有类似用法。例：The bike wants repairing.（自行车需要修理）"}], "tags": ["语法", "情态", "need"], "related": ["情态动词", "情态动词+have done", "非谓语动词"]}, {"id": "主将从现", "category": "语法·句法", "name": "主将从现", "level": "基础", "strength": "rule", "summary": "时间与条件状语从句用一般现在时表将来，主句才用将来时。", "rule": "when/while/as soon as/until/before/after 等时间连词和 if/unless/as long as 等条件连词引导状语从句时，从句用一般现在时表将来，主句用一般将来时（主将从现）；主句为祈使句或含情态动词时，从句同样用一般现在时。注意：if/when 引导宾语从句（表「是否/何时」）不受此限，仍可用将来时。", "examples": [{"sentence": "I will call you as soon as I arrive in Beijing.", "source": "高考真题改编", "answer": "as soon as 引导时间从句，用一般现在时表将来"}, {"sentence": "We will go climbing unless it rains tomorrow.", "source": "教材例句", "answer": "unless 引导条件从句，用一般现在时"}, {"sentence": "As long as you keep practicing, you will make progress.", "source": "教材例句", "answer": "as long as 条件从句用一般现在时"}, {"sentence": "Please let me know when he comes back.", "source": "教材例句", "answer": "主句为祈使句，when 从句仍用一般现在时"}], "commonErrors": [{"wrong": "If it will rain tomorrow, we will stay at home.", "right": "If it rains tomorrow, we will stay at home.", "why": "if 引导条件状语从句用一般现在时表将来，不能两处都用将来时"}, {"wrong": "I don\'t know if he comes tomorrow.", "right": "I don\'t know if he will come tomorrow.", "why": "此处 if 引导宾语从句（表是否），不适用主将从现，将来动作用 will come"}], "confusionPoints": [{"point": "if 条件状语从句 vs if 宾语从句", "detail": "条件从句「如果」用一般现在时表将来；宾语从句「是否」可用将来时。例：If he comes, I will tell him.（条件）vs I wonder if he will come.（是否）"}, {"point": "when 时间状语从句 vs when 宾语从句", "detail": "状语从句的 when 用一般现在时表将来；宾语从句的 when（何时）可用将来时。例：I will tell him when he comes.（一到就告诉）vs I don\'t know when he will come.（不知道何时来）"}], "tags": ["语法", "时态", "从句"], "related": ["状语从句", "动词时态", "名词性从句"]}, {"id": "定语从句that与which的选择", "category": "语法·句法", "name": "定语从句 that 与 which 的选择", "level": "进阶", "strength": "rule", "summary": "只用 that 与只用 which 的场景辨析；非限制性定语从句只用 which。", "rule": "先行词有特定修饰时只用 that；非限制性从句与介词后只能用 which。", "examples": [{"sentence": "All that can be done has been done.", "source": "教材例句", "answer": "先行词是不定代词 all，只用 that"}, {"sentence": "This is the best film that I have ever seen.", "source": "高考真题改编", "answer": "先行词被最高级修饰，只用 that"}, {"sentence": "He passed the exam, which made his parents happy.", "source": "高考真题改编", "answer": "非限制性定语从句用 which，指代整个主句"}, {"sentence": "She is the only person that can help us.", "source": "教材例句", "answer": "先行词被 the only 修饰，只用 that"}], "commonErrors": [{"wrong": "He said he had no friends, that surprised me.", "right": "He said he had no friends, which surprised me.", "why": "非限制性定语从句不能用 that 引导，指物或指代整句只能用 which"}, {"wrong": "Everything which he said is true.", "right": "Everything that he said is true.", "why": "先行词是不定代词 everything 时，关系代词只用 that"}], "confusionPoints": [{"point": "限制性从句中 that 与 which 的互换", "detail": "限制性定语从句指物时 that/which 多可互换，但先行词为不定代词或受最高级、序数词、the only 修饰时只用 that；非限制性从句只用 which"}, {"point": "which 指代整句", "detail": "非限制性定语从句中 which 可指代前面整个主句，that 无此用法。例：He was late again, which made the teacher angry.（这使得老师生气）"}], "tags": ["语法", "从句", "定语从句"], "related": ["定语从句", "介词+关系代词", "as引导的定语从句"], "points": [{"text": "先行词是不定代词 all / everything / nothing / anything / little / much", "example": "Everything that can be done has been done.", "note": "先行词 everything 属不定代词，只能用 that。"}, {"text": "先行词被序数词、最高级、the only / the very / the last 修饰", "example": "This is the best film that I have ever seen.", "note": "先行词被最高级 the best 修饰，只能用 that。"}, {"text": "先行词既有人又有物", "example": "They talked about the people and things that they remembered.", "note": "先行词同时含人和物，只能用 that。"}, {"text": "先行词被 all / any / every / no 等词修饰", "example": "There is no difficulty that we cannot overcome.", "note": "先行词被 no 修饰，宜用 that。"}, {"text": "疑问句以 who / which 开头时（避免重复）", "example": "Who is the man that is standing by the door?", "note": "句首已用 who 提问，关系词改用 that 以免重复。"}, {"text": "只用 which：非限制性定语从句（逗号隔开）指物，且可指代整个主句", "example": "He passed the exam, which delighted his parents.", "note": "which 指代整个主句，前面有逗号（非限制性）。"}]}, {"id": "介词+关系代词", "category": "语法·句法", "name": "介词+关系代词", "level": "挑战", "strength": "rule", "summary": "介词后接 which/whom 引导定语从句；介词的选择依据与前后位置有固定规则。", "rule": "介词后用 which / whom（指物 which、指人 whom，不能用 that / who）；介词可前置也可后置，固定短语的介词不可拆开提前。", "examples": [{"sentence": "This is the house in which I lived for ten years.", "source": "教材例句", "answer": "介词 in 前置，指物用 which"}, {"sentence": "The man to whom you spoke is our new teacher.", "source": "教材例句", "answer": "介词 to 前置，指人用 whom"}, {"sentence": "This is the house (which/that) I lived in for ten years.", "source": "教材例句", "answer": "介词后置时可用 which/that 或省略"}, {"sentence": "The camera with which he took photos was made in Japan.", "source": "高考真题改编", "answer": "with 与 take photos 搭配，前置用 which"}], "commonErrors": [{"wrong": "This is the house in that I lived.", "right": "This is the house in which I lived.", "why": "介词后不能用 that 引导定语从句，指物只能用 which"}, {"wrong": "The friend with who I traveled is from Canada.", "right": "The friend with whom I traveled is from Canada.", "why": "介词后指人的关系代词用 whom，不用 who"}], "confusionPoints": [{"point": "介词前置 vs 介词后置", "detail": "介词前置只能用 which/whom，语体正式；介词后置时可用 that/which/who/whom 或省略，较口语。例：the person to whom I wrote（正式）vs the person (who/that) I wrote to（口语）"}, {"point": "固定短语中介词不拆", "detail": "动词与介词构成固定短语时（如 look after, take care of），介词一般不拆到关系代词前。例：The baby (whom/that) she is looking after is cute.（不说 after whom she is looking）"}], "tags": ["语法", "从句", "定语从句"], "related": ["定语从句", "定语从句that与which的选择", "介词"], "points": [{"text": "介词的选择：看与先行词的习惯搭配，或与从句中动词 / 形容词的搭配", "example": "The room in which we had the meeting is on the second floor.", "note": "in which 相当于 in the room，介词 in 由「在房间里开会」这一搭配决定。"}, {"text": "指人时用 whom，不能用 who / that", "example": "The teacher to whom you spoke is our headmaster.", "note": "介词 to 前置且指人，必须用 whom。"}, {"text": "介词可后置（此时可用 that / who 或省略），但固定短语的介词不能拆开提前", "example": "This is the book that I told you about.", "note": "about 留在句末＝介词后置；而 look after 这类固定短语不能写成 after which。"}]}, {"id": "as引导的定语从句", "category": "语法·句法", "name": "as 引导的定语从句", "level": "挑战", "strength": "rule", "summary": "as 用于 such...as、the same...as 结构；引导非限制性定语从句时位置可前可后。", "rule": "as 用于 such ... as / the same ... as；引导非限制性从句时可指代整个主句，位置灵活（可置句首）。", "examples": [{"sentence": "Such books as you recommended are worth reading.", "source": "教材例句", "answer": "such...as 引导定语从句，as 作 recommended 的宾语"}, {"sentence": "He is not the same man as he used to be.", "source": "教材例句", "answer": "the same...as 引导定语从句"}, {"sentence": "As is known to all, the earth moves around the sun.", "source": "高考真题改编", "answer": "as 引导非限制性定语从句，可置于句首"}, {"sentence": "He was late again, as we had expected.", "source": "教材例句", "answer": "as 指代整个主句，置于句末"}], "commonErrors": [{"wrong": "He is such a kind man as everyone likes him.", "right": "He is such a kind man as everyone likes.", "why": "as 引导定语从句时须在从句中充当成分（此处作 likes 的宾语），从句中不能再出现多余的主语 him"}, {"wrong": "As everybody knows it, he is an honest man.", "right": "As everybody knows, he is an honest man.", "why": "as 引导定语从句时作从句的宾语，指代主句内容，从句内不能再出现 it 等多余的指代成分"}], "confusionPoints": [{"point": "as vs which 引导非限制性定语从句", "detail": "as 位置灵活（句首/句中/句末），常含「正如」义（as is known to all / as we expected）；which 只能置于主句之后，常表「这件事」引起的结果或评论"}, {"point": "such...as vs such...that", "detail": "such...as 引导定语从句，as 充当成分；such...that 引导结果状语从句，that 不充当成分且从句完整。例：This is such a good book as we all like.（定语）vs This is such a good book that everyone likes it.（结果）"}], "tags": ["语法", "从句", "定语从句"], "related": ["定语从句", "定语从句that与which的选择", "比较结构"], "points": [{"text": "先行词被 such / the same 修饰时用 as 引导，as 在从句中作主语、宾语或表语", "example": "Such books as are useful should be read carefully.", "note": "as 在从句中作主语，先行词被 such 修饰。"}, {"text": "as 引导非限制性定语从句指代整个主句，位置灵活；which 只能置于主句之后", "example": "As is known to all, the earth moves around the sun.", "note": "as 指代后面整个主句，且位于句首——which 不能放这里。"}]}, {"id": "情态动词+have done", "category": "语法·句法", "name": "情态动词+have done", "level": "挑战", "strength": "rule", "summary": "must/can\'t/should/needn\'t + have done 表对过去的推测或评价。", "rule": "情态动词 + have done 表对过去情况的推测或评价：must have done 表对过去的肯定推测（一定做了）；can\'t/couldn\'t have done 表对过去的否定推测（不可能做了）；should/ought to have done 表本应做而未做，含责备；needn\'t have done 表本不必做却做了；may/might have done 表过去也许做了。", "examples": [{"sentence": "The ground is wet. It must have rained last night.", "source": "教材例句", "answer": "must have done 对过去的肯定推测"}, {"sentence": "He can\'t have finished the work so soon.", "source": "高考真题改编", "answer": "can\'t have done 对过去的否定推测"}, {"sentence": "You should have told me earlier.", "source": "教材例句", "answer": "should have done 本应做而未做，含责备"}, {"sentence": "You needn\'t have come so early. The meeting was put off.", "source": "高考真题改编", "answer": "needn\'t have done 本不必做却做了"}], "commonErrors": [{"wrong": "He must not have gone to Beijing, for he was here just now.", "right": "He can\'t have gone to Beijing, for he was here just now.", "why": "对过去的否定推测用 can\'t have done；must not 不表否定推测"}, {"wrong": "You needn\'t come so early yesterday.", "right": "You needn\'t have come so early yesterday.", "why": "表过去本不必做却做了，用 needn\'t have done；needn\'t do 只表现在或将来的不必"}], "confusionPoints": [{"point": "should have done vs needn\'t have done", "detail": "should have done 表本应做而没做（责备/遗憾）；needn\'t have done 表本不必做却做了（多此一举）。例：You should have asked for leave.（该请假没请）vs You needn\'t have hurried.（不必赶时间）"}, {"point": "must have done 的否定与疑问", "detail": "must have done 的否定推测用 can\'t have done，疑问用 Can/Could he have done...?；must 本身没有否定推测的形式"}], "tags": ["语法", "情态", "推测"], "related": ["情态动词", "情态动词表推测", "虚拟语气"]}, {"id": "名词", "category": "语法·词法", "name": "名词", "level": "基础", "strength": "rule", "summary": "表示人、事物、抽象概念的名称；注意可数/不可数、单数/复数及主谓一致。", "rule": "名词分可数与不可数；可数名词有单复数变化(规则加 -s/-es，不规则如 child→children, sheep 单复同形)；不可数名词(如 news, advice, furniture)无复数、不接 a/an，表数量需量词；集合名词强调整体用单数、强调成员用复数。", "examples": [{"sentence": "The news is very exciting.", "source": "教材例句", "answer": "news 以 s 结尾但不可数，谓语用单数"}, {"sentence": "Physics is my favorite subject.", "source": "教材例句", "answer": "以 s 结尾的学科名词作单数"}, {"sentence": "The children are playing in the park.", "source": "教材例句", "answer": "child 的复数是不规则变化 children"}, {"sentence": "The sheep are eating grass.", "source": "教材例句", "answer": "sheep 单复数同形"}], "commonErrors": [{"wrong": "He has many homeworks to do.", "right": "He has much homework to do.", "why": "homework 不可数，不能用复数，应用 much 修饰"}, {"wrong": "These news are very important.", "right": "This news is very important.", "why": "news 不可数，谓语用单数"}], "confusionPoints": [{"point": "可数名词 vs 不可数名词", "detail": "不可数名词前不能直接加 a/an，变复数时需借助量词。例：a piece of advice（一条建议），two cups of tea（两杯茶）"}, {"point": "单复数同形的名词", "detail": "sheep, deer, fish, Chinese, Japanese 等单复数同形。例：one sheep, two sheep"}], "tags": ["语法", "词法", "名词"], "related": ["主谓一致", "限定词"]}, {"id": "代词", "category": "语法·词法", "name": "代词", "level": "基础", "strength": "rule", "summary": "代替名词或名词短语的词，包括人称、物主、反身、指示、不定代词等。", "rule": "代词按格使用：主格(I/he)作主语，宾格(me/him)作宾语/介词宾语，形容词性物主代词(my/his)作定语，名词性物主代词(mine/his)作主语/表语/宾语。反身代词(oneself)表强调或宾语与主语一致。", "examples": [{"sentence": "He is my teacher.", "source": "教材例句", "answer": "形容词性物主代词 his 作定语"}, {"sentence": "This book is mine.", "source": "教材例句", "answer": "名词性物主代词 mine 作表语"}, {"sentence": "The boy himself did it.", "source": "高考真题改编", "answer": "反身代词 himself 作同位语，表强调"}, {"sentence": "It is I who am responsible.", "source": "教材例句", "answer": "强调句中谓语与 who 后的主语一致"}], "commonErrors": [{"wrong": "Her is my sister.", "right": "She is my sister.", "why": "作主语应用主格 she，不能用形容词性物主代词 her"}, {"wrong": "Between you and I, he is not honest.", "right": "Between you and me, he is not honest.", "why": "介词 between 后应用宾格 me"}], "confusionPoints": [{"point": "it 的形式主语 vs 指示代词", "detail": "it 作形式主语代替后面的不定式/从句；指示代词 it 指代前面提到的事物。例：It is important to study.（形式）vs This is my book; it is new.（指示）"}, {"point": "one vs it", "detail": "it 指代前面提到的同一事物；one 指代同类事物中的任意一个。例：I like the book; I will buy it.（同一本）vs I do not have one.（任意一本）"}], "tags": ["语法", "词法", "代词"], "related": ["it的用法", "限定词"]}, {"id": "冠词", "category": "语法·词法", "name": "冠词", "level": "基础", "strength": "rule", "summary": "a/an 表泛指，the 表特指；球类/三餐前通常不用冠词。", "rule": "a 用于辅音音素开头的词前，an 用于元音音素开头的词前(看音素不看字母)；the 用于独一无二事物、乐器、特指；球类/棋类/三餐前不加 the；go to school 表上学不加 the，go to the school 表去学校办事加 the。", "examples": [{"sentence": "The earth moves around the sun.", "source": "教材例句", "answer": "独一无二的事物前加 the"}, {"sentence": "He plays the piano very well.", "source": "教材例句", "answer": "乐器名词前加 the"}, {"sentence": "We play football every day.", "source": "教材例句", "answer": "球类运动前不加冠词"}, {"sentence": "The rich are not always happy.", "source": "教材例句", "answer": "the + 形容词表一类人"}], "commonErrors": [{"wrong": "We will go to the school to see our teacher.", "right": "We will go to school to see our teacher.", "why": "go to school 是固定搭配表上学，不加 the；go to the school 表去学校办事"}, {"wrong": "He is a honest boy.", "right": "He is an honest boy.", "why": "honest 发音以元音开头，应用 an"}], "confusionPoints": [{"point": "不定冠词 a vs an", "detail": "a 用于辅音音素开头的词前；an 用于元音音素开头的词前。注意看音素不是字母。例：an hour（h 不发音），a university"}, {"point": "定冠词 the 的固定搭配", "detail": "in the morning/afternoon/evening 用 the；at night 不用 the。by bus/train/plane 不用 the；on foot 不用 the"}], "tags": ["语法", "词法", "冠词"], "related": ["限定词", "名词"]}, {"id": "介词", "category": "语法·词法", "name": "介词", "level": "基础", "strength": "rule", "summary": "用在名词/代词前，表示时间、地点、方式、原因等关系。", "rule": "介词后接名词/代词/动名词；in/on/at 表时间(年季月/具体天/时刻)与地点(大地点/表面街道/小地点)；arrive 后接 in(大)/at(小)；since 接时间点与完成时连用；固定搭配中介词不可替换。", "examples": [{"sentence": "He arrived at the station.", "source": "教材例句", "answer": "arrive at 后接小地点；arrive in 后接大地点"}, {"sentence": "We are proud of our country.", "source": "教材例句", "answer": "be proud of 固定搭配"}, {"sentence": "The book is on the desk.", "source": "教材例句", "answer": "on 表示在表面上面"}, {"sentence": "He has been here since 2020.", "source": "高考真题改编", "answer": "since 后接时间点，与现在完成时连用"}], "commonErrors": [{"wrong": "He is good in English.", "right": "He is good at English.", "why": "be good at 是固定搭配，不能用 in"}, {"wrong": "I will arrive Beijing tomorrow.", "right": "I will arrive in Beijing tomorrow.", "why": "arrive 是不及物动词，后接地点需加介词 in/at"}], "confusionPoints": [{"point": "in, on, at 表示时间", "detail": "in 用于年/月/季节/上午下午晚上；on 用于具体某天/某天的上下午晚上；at 用于时刻/中午/夜里。例：in 2020, on Monday morning, at 5 o\'clock"}, {"point": "in, on, at 表示地点", "detail": "in 用于大地点/在里面；on 用于在表面/街道；at 用于小地点/具体地址。例：in China, on Main Street, at 123 Main Street"}], "tags": ["语法", "词法", "介词"], "related": ["固定搭配辨析", "冠词"]}, {"id": "形容词", "category": "语法·词法", "name": "形容词", "level": "基础", "strength": "rule", "summary": "修饰名词或代词，表性质或特征；注意比较级与位置。", "rule": "形容词修饰名词；比较级单音节加 -er，多音节用 more；以 -ing 结尾表令人…的(修饰物)，以 -ed 结尾表感到…的(修饰人)；多个形容词顺序：限定词+描绘+大小+形状+新旧+颜色+国籍+材料+用途。", "examples": [{"sentence": "The beautiful flowers attracted many visitors.", "source": "教材例句", "answer": "形容词 beautiful 作定语"}, {"sentence": "He is taller than his brother.", "source": "教材例句", "answer": "形容词比较级 taller"}, {"sentence": "This is the most interesting book I have ever read.", "source": "高考真题改编", "answer": "形容词最高级 most interesting"}], "commonErrors": [{"wrong": "He is more taller than his brother.", "right": "He is taller than his brother.", "why": "单音节形容词比较级加 -er，不需要 more"}, {"wrong": "This book is more better than that one.", "right": "This book is better than that one.", "why": "good/well 的比较级是 better，不需要 more"}], "confusionPoints": [{"point": "形容词作定语的位置", "detail": "多个形容词修饰同一名词的顺序：限定词+描绘性+大小+形状+新旧+颜色+国籍+材料+用途。例：a beautiful small old brown Chinese wooden writing desk"}, {"point": "以 -ing 和 -ed 结尾的形容词", "detail": "-ing 形容词表令人…的，修饰物；-ed 形容词表感到…的，修饰人。例：an interesting book（令人感兴趣的）vs an interested boy（感兴趣的）"}], "tags": ["语法", "词法", "形容词"], "related": ["副词", "比较结构"]}, {"id": "副词", "category": "语法·词法", "name": "副词", "level": "基础", "strength": "rule", "summary": "修饰动词、形容词、其他副词或全句，表程度、方式、时间等。", "rule": "副词多由形容词加 -ly 构成，修饰动词/形容词/副词或全句；注意以 -ly 结尾的不一定都是副词(lonely, friendly, lovely 是形容词)；形副同形词(如 fast, hard, late)需结合语境判断。", "examples": [{"sentence": "He finally found his lost keys.", "source": "高考真题改编", "answer": "副词 finally 修饰动词 found"}, {"sentence": "Luckily, he was not hurt badly.", "source": "教材例句", "answer": "副词 luckily 修饰整个句子"}, {"sentence": "He ran quickly to catch the bus.", "source": "教材例句", "answer": "副词 quickly 修饰动词 ran"}], "commonErrors": [{"wrong": "He ran quick to catch the bus.", "right": "He ran quickly to catch the bus.", "why": "修饰动词应用副词 quickly，不能用形容词 quick"}, {"wrong": "He speaks English very good.", "right": "He speaks English very well.", "why": "修饰动词 speaks 应用副词 well"}], "confusionPoints": [{"point": "形容词 vs 副词", "detail": "形容词修饰名词；副词修饰动词、形容词、其他副词或整个句子。例：a quick walk（形）vs walk quickly（副）"}, {"point": "以 -ly 结尾的不一定是副词", "detail": "lonely, friendly, lovely, lively 等虽以 -ly 结尾，但仍是形容词。例：a friendly smile（形）vs smile in a friendly way（副）"}], "tags": ["语法", "词法", "副词"], "related": ["形容词", "比较结构"]}, {"id": "连词", "category": "语法·词法", "name": "连词", "level": "基础", "strength": "rule", "summary": "连接词、短语或从句，分并列连词与从属连词。", "rule": "并列连词(and, but, or, so, for)连接并列成分；从属连词(because, if, when, although, that)引导从句。中文可连用虽然…但是，英文中 although/though 与 but、because 与 so 不能连用。", "examples": [{"sentence": "He is young, but he knows a lot.", "source": "教材例句", "answer": "but 表转折"}, {"sentence": "He did not come because he was ill.", "source": "教材例句", "answer": "because 引导原因状语从句"}, {"sentence": "I do not know if he will come.", "source": "教材例句", "answer": "if 引导宾语从句，表是否"}], "commonErrors": [{"wrong": "Because he was ill, so he did not come.", "right": "Because he was ill, he did not come.", "why": "because 和 so 不能连用；也可只用一个连词，改为 He was ill, so he did not come."}, {"wrong": "Although he was tired, but he kept working.", "right": "Although he was tired, he kept working.", "why": "although/though 和 but 不能连用"}], "confusionPoints": [{"point": "并列连词 vs 从属连词", "detail": "并列连词(and, but, or, so)连接并列的词、短语或句子；从属连词(because, if, when, although)引导从句"}, {"point": "while 的多种用法", "detail": "while 可表当…时(时间)、虽然(让步)、而(对比)。例：While I was reading, he came in.（时间）vs While I understand your view, I disagree.（让步）"}], "tags": ["语法", "词法", "连词"], "related": ["状语从句", "写作衔接与过渡"]}, {"id": "限定词", "category": "语法·词法", "name": "限定词", "level": "基础", "strength": "rule", "summary": "置于名词前限定其意义，如 a/an、the、this、some、many、much、few 等。", "rule": "限定词修饰名词：many/a few/few 修饰可数名词复数；much/a little/little 修饰不可数名词；few/little 表否定(几乎没有)，a few/a little 表肯定(有一些)；each/every 修饰单数。", "examples": [{"sentence": "Many students like English.", "source": "教材例句", "answer": "many 修饰可数名词复数"}, {"sentence": "Much water is wasted.", "source": "教材例句", "answer": "much 修饰不可数名词"}, {"sentence": "Few people know the truth.", "source": "高考真题改编", "answer": "few 表否定，修饰可数名词"}], "commonErrors": [{"wrong": "Many water is wasted.", "right": "Much water is wasted.", "why": "water 不可数，应用 much 修饰"}, {"wrong": "Few people knows the truth.", "right": "Few people know the truth.", "why": "few 修饰复数名词，谓语用复数"}], "confusionPoints": [{"point": "many vs much", "detail": "many 修饰可数名词复数；much 修饰不可数名词。例：many books, much water"}, {"point": "few/a little vs a few/a little", "detail": "few/a few 修饰可数名词；little/a little 修饰不可数名词。few/little 表否定（几乎没有）；a few/a little 表肯定（有一些）"}], "tags": ["语法", "词法", "限定词"], "related": ["名词", "冠词"]}, {"id": "数词", "category": "语法·词法", "name": "数词", "level": "基础", "strength": "rule", "summary": "表示数目与顺序，含基数词、序数词、分数、小数、百分数与倍数表达。", "rule": "基数词表数量，序数词表顺序(加 th，特殊 first/second/third)；分数：分子基数、分母序数，分子>1 分母加 s；百分数 percent；倍数用 times 置于 as...as 或比较级前。分数/百分数作主语，谓语与 of 后名词数一致。", "examples": [{"sentence": "Two thirds of the students are girls.", "source": "教材例句", "answer": "分数 two thirds，谓语与 students 复数一致"}, {"sentence": "He came first in the race.", "source": "教材例句", "answer": "序数词 first 表顺序"}, {"sentence": "The price is 3.5 times that of last year.", "source": "高考真题改编", "answer": "倍数 3.5 times"}, {"sentence": "70 percent of the water is polluted.", "source": "教材例句", "answer": "百分数谓语与 water 单数一致"}], "commonErrors": [{"wrong": "One third of the books is lost.", "right": "One third of the books are lost.", "why": "分数作主语时谓语与 of 后名词一致，books 复数用 are"}, {"wrong": "three time as large as", "right": "three times as large as", "why": "表倍数时 time 用复数 times"}], "confusionPoints": [{"point": "分数/百分数谓语一致", "detail": "与 of 后名词一致。例：Two thirds of the money is...（money 不可数用 is）"}, {"point": "倍数表达", "detail": "倍数用 times，置于 as...as 或 比较级前。例：twice as many as"}], "tags": ["语法", "词法", "数词"], "related": ["主谓一致", "比较结构"]}, {"id": "不定代词", "category": "语法·词法", "name": "不定代词", "level": "进阶", "strength": "rule", "summary": "both/either/neither/all/none/each 在主谓一致与搭配上的差异。", "rule": "both（两者都）+ 复数名词，谓语用复数；either/neither（任一/两者都不）+ 单数名词，谓语用单数；all（三者及以上都）+ 复数名词或不可数名词；none（三者及以上都不）+ of 短语作主语时谓语单复皆可；each（每一个）+ 单数名词，each of + 复数名词，谓语均用单数。both...and 表都；either...or / neither...nor 连接主语时谓语就近一致。", "examples": [{"sentence": "Both of the answers are correct.", "source": "教材例句", "answer": "both 作主语，谓语用复数"}, {"sentence": "Neither answer is right.", "source": "高考真题改编", "answer": "neither + 单数名词，谓语用单数"}, {"sentence": "Each of the students has a dictionary.", "source": "教材例句", "answer": "each of + 复数名词，谓语仍用单数"}, {"sentence": "None of them has been to Beijing.", "source": "教材例句", "answer": "none of 作主语，谓语单复皆可（此处用单数）"}], "commonErrors": [{"wrong": "Both of them has been to Shanghai.", "right": "Both of them have been to Shanghai.", "why": "both 表两者都，作主语时谓语用复数"}, {"wrong": "Neither of the answers are correct.", "right": "Neither of the answers is correct.", "why": "neither 表两者都不，作主语时谓语按单数处理（规范用法）"}], "confusionPoints": [{"point": "both vs either vs neither", "detail": "both 两者都（复数）；either 两者中任一（单数）；neither 两者都不（单数）。例：Both doors are open. / Either door is fine. / Neither door is open."}, {"point": "neither vs none", "detail": "neither 只用于两者；none 用于三者及以上。例：Neither of my parents smokes.（父母两人都不）vs None of the three students passed.（三人都不）"}], "tags": ["语法", "词法", "代词"], "related": ["代词", "主谓一致", "限定词"]}, {"id": "指代词辨析", "category": "语法·词法", "name": "指代词辨析（it / one / that / those）", "level": "进阶", "strength": "rule", "summary": "it 同物单数，one 同类泛指，that 特指不可数或比较句，those 特指复数。", "rule": "it 指代前文提到的同一事物（同物单数）；one 指同类事物中的任意一个（同类泛指，复数为 ones）；that 指代前文特指的单数可数名词或不可数名词（= the one），后常接 of/in 短语，多用于比较句；those 是 that 的复数（= the ones），指代特指的复数名词。比较句中代替可数单数用 that 或 the one，代替复数用 those 或 the ones。", "examples": [{"sentence": "I have lost my pen. I am looking for it.", "source": "教材例句", "answer": "it 指同一支钢笔（同物）"}, {"sentence": "I don\'t have a dictionary. I want to buy one.", "source": "高考真题改编", "answer": "one 指同类中的一本（泛指）"}, {"sentence": "The weather in the south is warmer than that in the north.", "source": "高考真题改编", "answer": "that 指代比较句中特指的不可数名词 the weather"}, {"sentence": "The students in Class One are more active than those in Class Two.", "source": "教材例句", "answer": "those 指代特指的复数名词 the students"}], "commonErrors": [{"wrong": "The population of China is larger than those of India.", "right": "The population of China is larger than that of India.", "why": "population 是不可数名词，比较句中用 that 代替；those 只指代复数名词"}, {"wrong": "The cost of the trip is lower than one we expected.", "right": "The cost of the trip is lower than that we expected.", "why": "cost 是不可数名词，比较句中用 that 指代；one 只代替可数单数名词"}], "confusionPoints": [{"point": "it vs one", "detail": "it 指同名同物；one 指同类异物。例：Your bike is nice. I want to buy one.（同类的新车）vs I lost my bike. I can\'t find it.（就是那辆）"}, {"point": "that vs one", "detail": "that = the one，带特指限定（常接 of/in 短语），可代替不可数名词；one 泛指同类可数单数。例：The price of meat is higher than that of eggs. vs I need a bag; please pass me one."}], "tags": ["语法", "词法", "代词"], "related": ["代词", "it的用法", "比较结构"]}, {"id": "倍数表达法", "category": "语法·词法", "name": "倍数表达法", "level": "基础", "strength": "rule", "summary": "倍数置于比较级、as...as 或名词短语之前，三种固定句式可互换。", "rule": "倍数固定放在比较结构最前面；两倍用 twice；三种句式可互换。", "examples": [{"sentence": "This hall is five times as large as that one.", "source": "教材例句", "answer": "倍数 + as...as"}, {"sentence": "The new bridge is three times longer than the old one.", "source": "高考真题改编", "answer": "倍数 + 比较级 + than"}, {"sentence": "The earth is 49 times the size of the moon.", "source": "教材例句", "answer": "倍数 + the + 名词 + of"}, {"sentence": "Their house is twice the size of ours.", "source": "教材例句", "answer": "两倍用 twice，置于 the size of 前"}], "commonErrors": [{"wrong": "This room is two times as large as that one.", "right": "This room is twice as large as that one.", "why": "「两倍」用 twice，不用 two times；三倍及以上才用 数字 + times"}, {"wrong": "This building is as twice high as that one.", "right": "This building is twice as high as that one.", "why": "倍数必须置于 as...as 结构整体之前，不能插在 as 与形容词之间"}], "confusionPoints": [{"point": "三种句式的等值转换", "detail": "A is three times as large as B = A is three times larger than B = A is three times the size of B，三种句式可互换，倍数始终位于结构最前"}, {"point": "twice vs three times", "detail": "两倍用 twice；三倍及以上用 数字 + times。例：twice as many as；four times as long as"}], "tags": ["语法", "词法", "比较"], "related": ["数词", "比较结构", "形容词"], "points": [{"text": "倍数 + as + 原级 + as", "example": "This room is three times as large as that one.", "note": "三倍，用 as ... as 结构表达。"}, {"text": "倍数 + 比较级 + than", "example": "This room is three times larger than that one.", "note": "同一个意思换成比较级句式，倍数仍在最前。"}, {"text": "倍数 + the + 名词（size / length / height / width / number）+ of", "example": "This room is three times the size of that one.", "note": "用 the size of 这类名词短语表达；两倍说 twice，不说 two times。"}]}, {"id": "so与such的区别", "category": "语法·词法", "name": "so 与 such 的区别", "level": "基础", "strength": "rule", "summary": "so 修饰形容词/副词，such 修饰名词短语；so many/much/few/little 是特例。", "rule": "so + 形容词/副词（so beautiful）；such + (a/an) + (形容词) + 名词（such a beautiful girl / such beautiful girls / such fine weather）。特例：中心词为表数量的 many/few/much/little 时用 so（so many people / so little water）。可转换：so nice a girl = such a nice girl；so...that 与 such...that 均可引导结果状语从句。", "examples": [{"sentence": "She is so kind that everyone likes her.", "source": "教材例句", "answer": "so + 形容词，引导结果状语从句"}, {"sentence": "It was such a boring speech that some people left.", "source": "高考真题改编", "answer": "such + a + 形容词 + 名词"}, {"sentence": "He made so many mistakes in the exam.", "source": "教材例句", "answer": "so many + 复数名词（数量词特例）"}, {"sentence": "I have never seen such fine weather.", "source": "教材例句", "answer": "such + 不可数名词"}], "commonErrors": [{"wrong": "It is so nice weather today.", "right": "It is such nice weather today.", "why": "weather 是不可数名词，中心词是名词，应用 such；so 只直接修饰形容词/副词"}, {"wrong": "She has such many friends here.", "right": "She has so many friends here.", "why": "many/few/much/little（表数量）与名词连用时用 so，这是 such 规则的特例"}], "confusionPoints": [{"point": "so...that vs such...that", "detail": "so 修饰形容词/副词；such 修饰名词短语，两者可转换：so nice a girl that... = such a nice girl that...。例：He ran so fast that no one could catch him."}, {"point": "little 的两种含义", "detail": "little 表「小」时用 such（such little children）；表「少」时用 so（so little water）。判断依据是 little 指大小还是数量"}], "tags": ["语法", "词法", "搭配"], "related": ["形容词", "限定词", "状语从句"]}, {"id": "易混动词辨析", "category": "词汇·用法", "name": "易混动词辨析", "level": "进阶", "strength": "rule", "summary": "形近/义近动词易混，需结合搭配与词义准确辨析。", "rule": "常见易混动词：lie(躺 lay/lain/lying；撒谎 lied/lied/lying)、lay(放/下蛋 laid/laid/lying)、rise(不及物，升起) vs raise(及物，举起)、affect(动词，影响) vs effect(名词，效果)、say/speak/talk/tell 搭配不同、cost/spend/take/pay 表花费时主语与搭配不同。", "examples": [{"sentence": "The sun rises in the east.", "source": "教材例句", "answer": "rise 不及物，表升起"}, {"sentence": "He raised his hand.", "source": "教材例句", "answer": "raise 及物，表举起"}, {"sentence": "The rain affected our plan.", "source": "高考真题改编", "answer": "affect 动词，表影响"}, {"sentence": "It cost me ten yuan.", "source": "教材例句", "answer": "cost 主语是物，表花费"}], "commonErrors": [{"wrong": "He rised his voice.", "right": "He raised his voice.", "why": "rise 不及物无宾语，表举起用及物动词 raise"}, {"wrong": "The book effects me a lot.", "right": "The book affects me a lot.", "why": "effect 多作名词，作动词表影响用 affect"}], "confusionPoints": [{"point": "lie 躺 vs lie 撒谎 vs lay 放", "detail": "lie 表躺：lay/lain/lying；lie 表撒谎：lied/lied/lying；lay 表放/下蛋：laid/laid/lying。三词形极易混"}, {"point": "spend vs take vs pay vs cost", "detail": "spend 主语是人 + on sth / (in) doing；take 常用 it takes sb time to do；pay 主语是人 + for sth；cost 主语是物"}], "tags": ["词汇", "辨析"], "related": ["固定搭配辨析", "非谓语动词"]}, {"id": "固定搭配辨析", "category": "词汇·用法", "name": "固定搭配辨析", "level": "基础", "strength": "rule", "summary": "固定短语中的介词/结构不可随意替换，部分 to 为介词后接 doing。", "rule": "固定搭配中介词固定：be good at(不用 in)、be interested in(不用 at)、look forward to / pay attention to / be used to 中的 to 是介词后接动名词。误用介词或把 to 当不定式是高频错误。", "examples": [{"sentence": "He is fond of music.", "source": "教材例句", "answer": "be fond of 表喜欢"}, {"sentence": "We should pay attention to the environment.", "source": "高考真题改编", "answer": "pay attention to 表注意"}, {"sentence": "He succeeded in passing the exam.", "source": "教材例句", "answer": "succeed in doing 表成功做某事"}, {"sentence": "I am looking forward to hearing from you.", "source": "教材例句", "answer": "look forward to 中 to 是介词，后接 doing"}], "commonErrors": [{"wrong": "He is fond in music.", "right": "He is fond of music.", "why": "be fond of 固定搭配，不能用 in"}, {"wrong": "We should pay attention on the environment.", "right": "We should pay attention to the environment.", "why": "pay attention to 固定搭配，不能用 on"}], "confusionPoints": [{"point": "介词在固定搭配中不可替换", "detail": "be good at(非 in)、be interested in(非 at)、look forward to(非 for)"}, {"point": "to 可能是介词", "detail": "look forward to, pay attention to, be used to 中的 to 是介词，后接动名词。例：I am used to getting up early."}], "tags": ["词汇", "搭配"], "related": ["介词", "易混动词辨析"]}, {"id": "短语动词", "category": "词汇·用法", "name": "短语动词", "level": "进阶", "strength": "rule", "summary": "动词与副词/介词构成的固定搭配，含义常非字面，是高考高频。", "rule": "短语动词由 动词+副词/介词 构成，整体含义常固定；及物/不及物影响宾语位置：代词宾语必须放动词与副词中间；常见如 put off, give up, look up, turn out, carry out, come up with。give up 等后接动名词。", "examples": [{"sentence": "Please turn off the light.", "source": "教材例句", "answer": "turn off 关掉"}, {"sentence": "He looked up the word in the dictionary.", "source": "教材例句", "answer": "look up 查阅（代词放中间：look it up）"}, {"sentence": "The plan turned out successful.", "source": "高考真题改编", "answer": "turn out 结果是"}, {"sentence": "She came up with a good idea.", "source": "教材例句", "answer": "come up with 想出"}], "commonErrors": [{"wrong": "Look up it in the dictionary.", "right": "Look it up in the dictionary.", "why": "代词宾语必须放在动词与副词中间"}, {"wrong": "He gave up to swim.", "right": "He gave up swimming.", "why": "give up 后接动名词"}], "confusionPoints": [{"point": "宾语位置", "detail": "名词宾语可在后或中间；代词宾语必须在动词与副词之间。例：turn it off（非 turn off it）"}, {"point": "及物 vs 不及物短语", "detail": "有的短语动词不接宾语(如 break out)，有的必须接(如 look into sth)"}], "tags": ["词汇", "短语"], "related": ["易混动词辨析", "固定搭配辨析"]}, {"id": "易混名词辨析", "category": "词汇·用法", "name": "易混名词辨析", "level": "进阶", "strength": "rule", "summary": "形近/义近名词需辨析搭配与语境。", "rule": "常见易混名词：effect(效果/结果,名)/affect(动词影响)；work(不可数工作)/job(可数职业)；accident(意外/事故)/incident(事件/事变)；reason(理由)/cause(原因)；family/home/house 侧重不同（family 家庭成员，home 家乡情感，house 建筑物）。", "examples": [{"sentence": "The medicine had no effect.", "source": "教材例句", "answer": "effect 名词效果"}, {"sentence": "He has a good job.", "source": "教材例句", "answer": "job 可数职业"}, {"sentence": "The accident was caused by carelessness.", "source": "高考真题改编", "answer": "accident 意外事故"}, {"sentence": "What is the cause of the fire?", "source": "教材例句", "answer": "cause 原因"}], "commonErrors": [{"wrong": "The accident had a big affect.", "right": "The accident had a big effect.", "why": "affect 是动词，名词用 effect"}, {"wrong": "He has much works to do.", "right": "He has much work to do.", "why": "work 不可数，job 才可数"}], "confusionPoints": [{"point": "effect vs affect", "detail": "effect 多作名词效果/影响；affect 作动词影响。例：The rain affected (v.) the game. / The effect (n.) was clear."}, {"point": "work vs job", "detail": "work 不可数指工作；job 可数指职业/职位。例：a part-time job"}], "tags": ["词汇", "辨析"], "related": ["易混动词辨析", "固定搭配辨析"]}, {"id": "易混形容词副词辨析", "category": "词汇·用法", "name": "易混形容词/副词辨析", "level": "进阶", "strength": "rule", "summary": "形近形容词/副词（如 lonely/alone, hard/hardly）含义不同，易误用。", "rule": "常见易混：lonely(孤独的,形)/alone(独自,形/副)；hard(努力/硬,形/副)/hardly(几乎不,副)；late(迟)/later(后来)/lately(最近)；close(近)/closely(仔细地)；deep/deeply；high/highly。注意 hardly 是几乎不，不是 hard 的副词。", "examples": [{"sentence": "He lives alone but he is not lonely.", "source": "教材例句", "answer": "alone 独自；lonely 孤独"}, {"sentence": "I can hardly understand it.", "source": "教材例句", "answer": "hardly 几乎不（非 hard 的副词）"}, {"sentence": "He works hard.", "source": "教材例句", "answer": "hard 努力（形/副）"}, {"sentence": "Have you seen him lately?", "source": "教材例句", "answer": "lately 最近"}], "commonErrors": [{"wrong": "I am very alone.", "right": "I feel very lonely.", "why": "alone 表客观独自不表感受，主观孤独用 lonely"}, {"wrong": "He hardly works.", "right": "He works hard.", "why": "hardly 是几乎不；表努力工作用 work hard"}], "confusionPoints": [{"point": "hard vs hardly", "detail": "hard 形/副硬/努力；hardly 副几乎不。例：He hardly worked.（几乎没做）"}, {"point": "alone vs lonely", "detail": "alone 客观独自；lonely 主观孤独的。例：The old man lives alone but not lonely."}], "tags": ["词汇", "辨析"], "related": ["形容词", "副词"]}, {"id": "近义词辨析", "category": "词汇·用法", "name": "近义词辨析", "level": "基础", "strength": "tendency", "summary": "义近词（如 say/speak/talk/tell, big/large/great）按搭配与语境区分。", "rule": "say 后接话语内容；speak 后接语言或演讲(speak to sb)；talk 强调交谈(talk with/about)；tell 后接人+内容(tell sb sth / tell a story)。big/large/great：big 口语大；large 侧重面积/范围；great 含伟大/重要。", "examples": [{"sentence": "He said he was tired.", "source": "教材例句", "answer": "say 接内容"}, {"sentence": "She speaks English well.", "source": "教材例句", "answer": "speak 接语言"}, {"sentence": "They are talking about the film.", "source": "教材例句", "answer": "talk about 谈论"}, {"sentence": "Tell me a story.", "source": "教材例句", "answer": "tell 接人+事"}], "commonErrors": [{"wrong": "He said me the news.", "right": "He told me the news.", "why": "tell 接双宾语（tell sb sth），say 不接人的宾语"}, {"wrong": "She spoke me in English.", "right": "She spoke to me in English.", "why": "speak 后接人需加介词 to"}], "confusionPoints": [{"point": "say vs tell", "detail": "say 接内容(say sth)；tell 接人+内容(tell sb sth)。例：say hello（固定）vs tell a lie"}, {"point": "speak vs talk", "detail": "speak 较正式/接语言；talk 强调双向交谈。例：speak at the meeting vs talk with friends"}], "tags": ["词汇", "辨析"], "related": ["易混动词辨析", "写作衔接与过渡"]}, {"id": "词性转换（派生法）", "category": "词汇·用法", "name": "词性转换（派生法）", "level": "进阶", "strength": "rule", "summary": "通过前后缀派生名词/形容词/副词，是语法填空与写作高频考点。", "rule": "常见后缀：名词 -tion/-ment/-ness/-ity；形容词 -ful/-less/-able/-ive/-al；副词 -ly；否定 un-/in-/im-/dis-。注意拼写变化：去 e 加 -ment(judge→judgment)、重读闭音节双写(occur→occurrence, prefer→preference)、以 ue 结尾去 e 加 ly(true→truly)。", "examples": [{"sentence": "develop → development", "source": "高考真题改编", "answer": "动词加 -ment 变名词"}, {"sentence": "care → careful → carefully", "source": "教材例句", "answer": "形/副派生"}, {"sentence": "able → unable", "source": "教材例句", "answer": "否定前缀 un-"}, {"sentence": "nation → national", "source": "教材例句", "answer": "-al 变形容词"}], "commonErrors": [{"wrong": "occurence", "right": "occurrence", "why": "occur 重读闭音节双写 r 再加 -ence"}, {"wrong": "true → truely", "right": "true → truly", "why": "以 ue 结尾的词去 e 加 ly"}], "confusionPoints": [{"point": "名词 vs 形容词后缀", "detail": "-tion 变名词；-ful/-ive 变形容词。例：act→action(名) vs active(形)"}, {"point": "双写规则", "detail": "重读闭音节辅元辅双写：occur→occurrence, prefer→preference, run→runner"}], "tags": ["词汇", "派生"], "related": ["名词", "形容词", "副词"]}, {"id": "动词接续（doing与to do）", "category": "词汇·用法", "name": "动词接续（doing 与 to do）", "level": "进阶", "strength": "rule", "summary": "部分动词只接 doing，部分只接 to do，remember/forget/regret 等两态语义不同。", "rule": "只接 doing：enjoy, avoid, finish, mind, practise, suggest, keep, miss, admit 等；只接 to do：want, hope, decide, refuse, agree, plan, manage, afford 等。stop to do（停下来去做另一事）与 stop doing（停止正在做的事）语义不同。remember/forget/regret + doing 表动作已发生，+ to do 表动作尚未发生。try doing（试着做）与 try to do（努力设法做）、mean doing（意味着）与 mean to do（打算做）语义有别。", "examples": [{"sentence": "Would you mind opening the window?", "source": "教材例句", "answer": "mind 后接 doing"}, {"sentence": "He decided to study abroad next year.", "source": "教材例句", "answer": "decide 后接 to do"}, {"sentence": "I remembered locking the door, but it was still open.", "source": "高考真题改编", "answer": "remember doing 表记得做过（锁过门）"}, {"sentence": "Remember to close the window when you leave.", "source": "教材例句", "answer": "remember to do 表记得要做（还没做）"}], "commonErrors": [{"wrong": "I enjoy to read novels in my spare time.", "right": "I enjoy reading novels in my spare time.", "why": "enjoy 后只能接动名词 doing，不接不定式"}, {"wrong": "The doctor advised him to give up to smoke.", "right": "The doctor advised him to give up smoking.", "why": "give up 后接动名词；finish/practise/keep 等词也接 doing"}], "confusionPoints": [{"point": "stop to do vs stop doing", "detail": "stop to do 表停下来去做另一件事；stop doing 表停止正在做的事。例：He stopped to have a rest.（停下来休息）vs He stopped smoking.（戒烟）"}, {"point": "forget/regret + doing vs to do", "detail": "+ doing 表动作已发生；+ to do 表动作尚未发生。例：I forgot meeting him before.（忘了曾见过）vs Don\'t forget to meet him.（别忘了要去见）"}], "tags": ["词汇", "非谓语", "搭配"], "related": ["非谓语动词", "短语动词", "固定搭配辨析"]}, {"id": "写作高级句型", "category": "写作·表达", "name": "写作高级句型", "level": "进阶", "strength": "register", "summary": "用非谓语、倒装、强调、从句等提升写作句式的多样性与层次。", "rule": "非谓语、倒装、强调句、定语从句、主语从句交替使用提升句式层次；忌通篇简单句。", "examples": [{"sentence": "Walking in the park, I saw a flower show.", "source": "写作范例", "answer": "现在分词作状语，简洁生动"}, {"sentence": "Only by practicing can we improve.", "source": "写作范例", "answer": "only + 状语引起部分倒装"}, {"sentence": "It was his kindness that moved me.", "source": "写作范例", "answer": "强调句突出重点"}, {"sentence": "What impressed me most was his smile.", "source": "写作范例", "answer": "主语从句开头，提升档次"}], "commonErrors": [{"wrong": "Only by practicing we can improve.", "right": "Only by practicing can we improve.", "why": "only + 状语置于句首要部分倒装"}, {"wrong": "Walking in the park, a flower show was seen.", "right": "Walking in the park, I saw a flower show.", "why": "分词作状语的逻辑主语须与主句主语一致"}], "confusionPoints": [{"point": "倒装 vs 陈述", "detail": "否定词/only 等置于句首才倒装，平时用陈述语序"}, {"point": "非谓语作状语的逻辑主语", "detail": "必须与主句主语一致，否则悬垂。例：To get there on time, we left early.（we 是 to get 的逻辑主语）"}], "tags": ["写作", "句型"], "related": ["倒装句", "强调句", "非谓语动词"], "points": [{"text": "非谓语动词作状语 / 定语", "example": "Walking along the river, I noticed a small boat.", "note": "现在分词作状语，其逻辑主语须与主句主语一致（都是 I）。"}, {"text": "倒装（Only / Not only / Never 等置于句首）增强语气", "example": "Not only did he finish the task, but he also helped others.", "note": "Not only 提前，主句用部分倒装 did he finish。"}, {"text": "强调句突出重点", "example": "It was her encouragement that gave me the strength.", "note": "用 It was ... that 把 her encouragement 推到焦点。"}, {"text": "定语从句合并信息", "example": "He lives in a village which lies at the foot of the hill.", "note": "用定语从句把两个短句并成一句，层次更紧。"}, {"text": "主语从句开头提升档次", "example": "What impressed me most was his honesty.", "note": "what 引导主语从句，充当整句主语。"}]}, {"id": "写作衔接与过渡", "category": "写作·表达", "name": "写作衔接与过渡", "level": "基础", "strength": "register", "summary": "用衔接词与过渡使段落间、句间逻辑清晰连贯。", "rule": "按语义选用衔接词：递进(besides, furthermore)、转折(however, yet)、因果(therefore, as a result)、举例(for example, such as)、总结(in conclusion)。段落结构用主题句+支撑句+小结；because/although 不与 so/but 连用。", "examples": [{"sentence": "However, we should also consider the cost.", "source": "写作范例", "answer": "however 表转折"}, {"sentence": "As a result, he failed the exam.", "source": "写作范例", "answer": "as a result 表结果"}, {"sentence": "For example, reading widely helps writing.", "source": "写作范例", "answer": "for example 表举例"}, {"sentence": "In conclusion, practice makes perfect.", "source": "写作范例", "answer": "in conclusion 表总结"}], "commonErrors": [{"wrong": "Because he was ill, so he did not come.", "right": "Because he was ill, he did not come.", "why": "because 与 so 不连用"}, {"wrong": "Although he tried, but he failed.", "right": "Although he tried, he failed.", "why": "although 与 but 不连用"}], "confusionPoints": [{"point": "递进 vs 转折", "detail": "besides/furthermore 表递进；however/yet 表转折，不可混用"}, {"point": "因果衔接", "detail": "therefore/thus/as a result 表结果；because/since 表原因，避免与 so 连用"}], "tags": ["写作", "衔接"], "related": ["连词", "写作高级句型"]}, {"id": "读后续写技巧", "category": "写作·表达", "name": "读后续写技巧", "level": "挑战", "strength": "register", "summary": "新高考读后续写：顺原文线索、人物与情节合理延展，重描写与衔接。", "rule": "顺原文线索延展情节，重描写与衔接，结尾点题；忌脱离原文胡编或突兀收尾。", "examples": [{"sentence": "Reading the given sentences, I found a clue to continue the story.", "source": "写作范例", "answer": "顺段首语延展"}, {"sentence": "With tears in her eyes, she hugged her mother tightly.", "source": "写作范例", "answer": "动作+情感描写"}, {"sentence": "The sunlight poured in, warming everything around.", "source": "写作范例", "answer": "环境描写烘托"}, {"sentence": "From then on, they learned the value of honesty.", "source": "写作范例", "answer": "结尾升华"}], "commonErrors": [{"wrong": "The story ended suddenly without connection.", "right": "The story developed naturally from the clues given in the passage.", "why": "续写须与原文线索衔接，情节自然发展，不可突兀收尾"}, {"wrong": "He very happy.", "right": "He was very happy.", "why": "描写需用完整句子，主谓齐全"}], "confusionPoints": [{"point": "描写 vs 叙述", "detail": "续写重描写(show not tell)：用动作、神态、环境体现情绪，而非直接说 happy/sad"}, {"point": "两段衔接", "detail": "必须分别使用两个给定段首语，且两段情节连贯递进"}], "tags": ["写作", "续写"], "related": ["写作高级句型", "写作衔接与过渡"], "points": [{"text": "细读原文，抓住人物、冲突与线索词", "example": "She kept looking at the old photo, saying nothing.", "note": "反复出现的「旧照片」就是线索词，续写必须接住它，不能另起无关情节。"}, {"text": "两个段首语必用，情节顺势发展", "example": "The next morning, she made up her mind.", "note": "段首语是命题人给的起点，续写从这里往下写，不跳时间线、不换人物。"}, {"text": "多用动作 / 心理 / 环境描写代替平铺直叙（show, not tell）", "example": "Her hands trembled as she unfolded the letter.", "note": "用动作细节「演」出紧张，而不是直接写 She was very nervous。"}, {"text": "恰当衔接词保证连贯", "example": "As soon as he heard the news, he rushed out; meanwhile, the rain began to pour.", "note": "时间与并列衔接词把两个动作自然咬合。"}, {"text": "结尾点题或升华", "example": "From that day on, she never judged a person by appearance again.", "note": "结尾回扣「不以貌取人」，把一件小事提到道理层面。"}]}, {"id": "应用文写作结构", "category": "写作·表达", "name": "应用文写作结构", "level": "基础", "strength": "register", "summary": "书信/通知等应用文有固定格式与套句，注意语气与要点覆盖。", "rule": "应用文结构：称呼→ opening(寒暄/点题)→ body(分点写清要点)→ closing(期待/祝福)→ 署名。书信开头 Dear...，结尾 Yours...；通知用 Notice + 时间地点；语气依对象正式/非正式；必须覆盖所有给定要点。", "examples": [{"sentence": "Dear Mr. Smith, I am writing to invite you to...", "source": "写作范例", "answer": "书信开头套句"}, {"sentence": "I would appreciate it if you could...", "source": "写作范例", "answer": "礼貌请求套句"}, {"sentence": "Notice: A lecture will be held at...", "source": "写作范例", "answer": "通知格式"}, {"sentence": "Looking forward to your reply.", "source": "写作范例", "answer": "结尾套句"}], "commonErrors": [{"wrong": "I very like your school.", "right": "I like your school very much.", "why": "very 不修饰动词 like，用 very much"}, {"wrong": "Dear friend: (随意称呼)", "right": "Dear Mr. Smith,", "why": "应用文需恰当称呼与逗号，依对象调整正式度"}], "confusionPoints": [{"point": "正式 vs 非正式", "detail": "给陌生人/老师用正式语体与 Yours sincerely；给朋友可随意。例：Wish you success.（正式）vs Hope to see you.（随意）"}, {"point": "要点覆盖", "detail": "应用文须覆盖所有给定要点，遗漏扣分；用连接词分点清晰"}], "tags": ["写作", "应用文"], "related": ["写作衔接与过渡", "写作高级句型"]}]');
